"""Pick work: NonMatching units and uncarved (auto-generated) code, minus what
open pull requests already touch.

usage:
  python3 .agents/scripts/alvos.py prs                 # refresh build/agent_cache/prs.json from GitHub
  python3 .agents/scripts/alvos.py nonmatching         # the units with source still NonMatching
  python3 .agents/scripts/alvos.py auto [-m stage11D] [--min 400] [-n 40]
  python3 .agents/scripts/alvos.py modules             # uncarved code per module

Reads build/G9SE8P/report.json (run `ninja` first; it is regenerated by the
PROGRESS step). `prs` fetches every open PR's file list and the .text ranges it
adds to any splits.txt, so `auto` can flag regions somebody is already carving
(PR!). Claimed modules (advertiseD, autosaveD) are always flagged.

An auto unit name encodes its start: main/auto_fn_8001D764_text,
stage11D/auto_00_000003E0_text (section-relative for RELs, like splits.txt).
"""

from __future__ import annotations

import argparse
import collections
import json
import os
import re
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _units import ROOT  # noqa: E402

REPORT = ROOT / "build" / "G9SE8P" / "report.json"
CACHE = ROOT / "build" / "agent_cache" / "prs.json"  # build/ is gitignored
CLAIMED = {"advertiseD": "CYPRESS", "autosaveD": "ThePlayerRolo"}


def report() -> dict:
    if not REPORT.exists():
        sys.exit("build/G9SE8P/report.json missing: run ninja")
    return json.loads(REPORT.read_text(encoding="utf-8"))


def gh(*args: str) -> str:
    r = subprocess.run(["gh", *args], cwd=ROOT, capture_output=True, text=True, encoding="utf-8")
    if r.returncode != 0:
        sys.exit(r.stderr)
    return r.stdout


def refresh_prs() -> None:
    old = json.loads(CACHE.read_text(encoding="utf-8")) if CACHE.exists() else {}
    prs = json.loads(gh("pr", "list", "--state", "open", "--limit", "300", "--json",
                        "number,author,title,headRefName,headRefOid,files"))
    out = {}
    for p in prs:
        key = str(p["number"])
        if key in old and old[key].get("oid") == p["headRefOid"]:
            out[key] = old[key]
            continue
        ranges = []
        if any(f["path"].endswith("splits.txt") for f in p["files"]):
            diff = gh("pr", "diff", key)
            module = None
            for line in diff.splitlines():
                m = re.match(r"diff --git a/config/G9SE8P/(?:(\w+)/)?splits\.txt", line)
                if line.startswith("diff --git"):
                    module = (m.group(1) or "main") if m else None
                    continue
                if module and line.startswith("+"):
                    t = re.search(r"\.text\s+start:0x([0-9A-Fa-f]+)\s+end:0x([0-9A-Fa-f]+)", line)
                    if t:
                        ranges.append([module, int(t.group(1), 16), int(t.group(2), 16)])
        out[key] = {
            "oid": p["headRefOid"], "author": p["author"]["login"], "title": p["title"],
            "branch": p["headRefName"], "files": [f["path"] for f in p["files"]], "text_ranges": ranges,
        }
    CACHE.parent.mkdir(parents=True, exist_ok=True)
    CACHE.write_text(json.dumps(out, indent=1), encoding="utf-8")
    authors = collections.Counter(v["author"] for v in out.values())
    print(f"{len(out)} open PRs cached in {CACHE.relative_to(ROOT)}: {dict(authors)}")


def prs() -> dict:
    if not CACHE.exists():
        print("(no PR cache: run `alvos.py prs` to flag regions open PRs already cover)\n")
        return {}
    return json.loads(CACHE.read_text(encoding="utf-8"))


def pr_flags(module: str, start: int, end: int, src: str | None, cache: dict) -> str:
    src_hits, range_hits = [], []
    for num, p in cache.items():
        if src and src in p["files"]:
            src_hits.append(num)
        for mod, a, b in p["text_ranges"]:
            if mod == module and a < end and start < b:
                range_hits.append(num)
                break

    def short(nums: list[str]) -> str:
        nums = sorted(set(nums), key=int)
        return ",".join(nums[:4]) + (f",+{len(nums) - 4}" if len(nums) > 4 else "")

    parts = []
    if range_hits:
        parts.append(f"RANGE in PR {short(range_hits)}")
    if src_hits:
        parts.append(f"src edited by {len(set(src_hits))} PRs ({short(src_hits)})")
    flag = "; ".join(parts)
    if module in CLAIMED:
        flag = (flag + " " if flag else "") + f"CLAIMED({CLAIMED[module]})"
    return flag


def unit_range(u: dict) -> tuple[str, int, int]:
    module = u["name"].split("/")[0]
    for s in u.get("sections", []):
        if s["name"] == ".text":
            va = int(s["metadata"]["virtual_address"])
            return module, va, va + int(s["size"])
    return module, 0, 0


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["prs", "nonmatching", "auto", "modules"])
    ap.add_argument("-m", "--module")
    ap.add_argument("--min", type=int, default=0, help="minimum code bytes")
    ap.add_argument("-n", type=int, default=40)
    a = ap.parse_args()
    if a.cmd == "prs":
        refresh_prs()
        return
    r = report()
    cache = prs()
    units = r["units"]
    if a.cmd == "modules":
        by = collections.defaultdict(lambda: [0, 0, 0])
        for u in units:
            m = u["name"].split("/")[0]
            code = int(u["measures"].get("total_code", 0))
            if (u.get("metadata") or {}).get("auto_generated"):
                by[m][0] += code
            else:
                by[m][1] += code
                by[m][2] += int(u["measures"].get("matched_code", 0))
        print(f"{'module':12} {'uncarved KiB':>12} {'carved KiB':>10} {'matched KiB':>11}")
        for m, (au, ca, ma) in sorted(by.items(), key=lambda kv: -kv[1][0]):
            print(f"{m:12} {au / 1024:12.1f} {ca / 1024:10.1f} {ma / 1024:11.1f}  {CLAIMED.get(m, '')}")
        return
    if a.cmd == "nonmatching":
        rows = [u for u in units if not (u.get("metadata") or {}).get("auto_generated")
                and not (u.get("metadata") or {}).get("complete")]
        rows.sort(key=lambda u: -(u["measures"].get("fuzzy_match_percent") or 0))
        print(f"{'unit':48} {'fuzzy':>7} {'matched%':>8} {'code':>6} {'funcs':>9}")
        for u in rows:
            me = u["measures"]
            mod, s, e = unit_range(u)
            src = (u.get("metadata") or {}).get("source_path")
            print(f"{u['name']:48.48} {me.get('fuzzy_match_percent', 0):7.2f} "
                  f"{me.get('matched_code_percent', 0):8.2f} {me.get('total_code', 0):>6} "
                  f"{me.get('matched_functions', 0):>4}/{me.get('total_functions', 0):<4} "
                  f"{pr_flags(mod, s, e, src, cache)}")
        return
    rows = [u for u in units if (u.get("metadata") or {}).get("auto_generated") and u["name"].endswith("_text")]
    if a.module:
        rows = [u for u in rows if u["name"].startswith(a.module + "/")]
    rows = [u for u in rows if int(u["measures"].get("total_code", 0)) >= a.min]
    rows.sort(key=lambda u: -int(u["measures"].get("total_code", 0)))
    print(f"{'auto unit':40} {'code':>7} {'funcs':>5}")
    for u in rows[: a.n]:
        me = u["measures"]
        mod, s, e = unit_range(u)
        print(f"{u['name']:40} {me.get('total_code', 0):>7} {me.get('total_functions', 0):>5}  "
              f"{pr_flags(mod, s, e, None, cache)}")


if __name__ == "__main__":
    main()
